<script setup>
import { computed, onMounted, reactive, ref } from 'vue'
import { request } from '../../services/request.js'
import { showError as showGlobalError } from '../../services/notification.js'

const loading = ref(true), saving = ref(false), testingTts = ref(false), testingAccount = ref(false), testingTemporaryToken = ref(false), changingProductionToken = ref(false), error = ref(''), errorCode = ref(''), ttsTest = ref(null), accountTest = ref(null), temporaryTokenTest = ref(null), tab = ref('models'), showForm = ref(false)
const models = ref([]), usage = ref({ logs: [], budget: null })
const budgetFeedback = ref(null)
const pricingStatus = ref({ enabled: true, lastStatus: 'not_run', lastCheckedAt: null, schedule: '每天 22:00', timezone: 'Asia/Shanghai' })
const budget = reactive({ limitAmount: '', currency: 'CNY' })
const tts = reactive({ provider: 'aliyun_nls', endpoint: 'https://nls-gateway-cn-shanghai.aliyuncs.com/stream/v1/tts', voice: 'aixia', sampleRate: 16000, appKey: '', accessKeyId: '', accessKeySecret: '', logs: [] })
const consoleAccountId = ref(''), temporaryNlsToken = ref(''), temporaryText = ref('Hello, this is a temporary NLS token test.')
const emptyForm = () => ({ id: '', providerCode: 'deepseek', modelCode: '', displayName: '', specification: 'flash', baseUrl: 'https://api.deepseek.com/chat/completions', apiKeyParamKey: 'AI_DEEPSEEK_API_KEY', apiKey: '', enabled: false, defaultModel: false, maxOutputTokens: 1200, timeoutSeconds: 60, currency: 'CNY', inputPerMillion: 0, outputPerMillion: 0, expectedVersion: null })
const form = reactive(emptyForm())
const budgetRate = computed(() => { const row = usage.value.budget; if (!row || !Number(row.limit_amount)) return 0; return Math.min(100, Math.round((Number(row.spent_amount || 0) + Number(row.reserved_amount || 0)) * 100 / Number(row.limit_amount))) })
const errorHelp = computed(() => errorCode.value === 'CREDENTIAL_ENCRYPTION_NOT_CONFIGURED' ? "启动后端前设置环境变量 AI_CREDENTIAL_ENCRYPTION_KEY（至少 32 位随机字符串），然后重启后端并重新保存本页密钥。不要使用示例值。" : '')

function clearError() { error.value = ''; errorCode.value = '' }
function showError(e, fallback = '操作失败，请稍后重试') { error.value = e?.message || fallback; errorCode.value = e?.code || ''; showGlobalError(e, fallback) }

async function load() {
  loading.value = true; clearError()
  try {
    const [modelRows, usageData, ttsData, priceState] = await Promise.all([request('/admin/ai/models'), request('/admin/ai/usage'), request('/admin/ai/tts'), request('/admin/ai/pricing/status')])
    models.value = modelRows; usage.value = usageData; pricingStatus.value = priceState; Object.assign(tts, ttsData, { appKey: '', accessKeyId: '', accessKeySecret: '' })
    if (usageData.budget) { budget.limitAmount = usageData.budget.limit_amount; budget.currency = usageData.budget.currency }
  } catch (e) { showError(e, 'AI 配置加载失败') } finally { loading.value = false }
}
function createModel() { clearError(); Object.assign(form, emptyForm()); showForm.value = true }
function editModel(model) { clearError(); Object.assign(form, emptyForm(), model, { id: model.id, apiKey: '', expectedVersion: model.versionNo }); showForm.value = true }
async function saveModel() {
  saving.value = true; clearError()
  try { const path = form.id ? `/admin/ai/models/${form.id}` : '/admin/ai/models'; await request(path, { method: form.id ? 'PUT' : 'POST', body: JSON.stringify(form) }); showForm.value = false; await load() }
  catch (e) { showError(e, '模型保存失败') } finally { saving.value = false }
}
async function saveBudget() {
  saving.value = true; clearError(); budgetFeedback.value=null
  try {
    usage.value = await request('/admin/ai/budget', { method: 'PUT', body: JSON.stringify(budget) })
    if (usage.value.budget) { budget.limitAmount=usage.value.budget.limit_amount; budget.currency=usage.value.budget.currency }
    budgetFeedback.value={ type:'success', text:`预算已保存：本月上限 ${budget.limitAmount} ${budget.currency}` }
  } catch (e) {
    budgetFeedback.value={ type:'error', text:e?.message || '预算保存失败，请稍后重试' }
    showError(e, '预算保存失败')
  } finally { saving.value = false }
}
async function reconcile(row) { const raw = window.prompt('请输入供应商账单核定费用（未收费输入 0）', '0'); if (raw === null) return; clearError(); try { usage.value = await request(`/admin/ai/attempts/${value(row,'id')}/reconcile`, { method: 'PUT', body: JSON.stringify({ settledAmount: raw }) }) } catch (e) { showError(e, '费用核对失败') } }
async function saveTts() { saving.value = true; clearError(); try { const data = await request('/admin/ai/tts', { method: 'PUT', body: JSON.stringify(tts) }); Object.assign(tts, data, { appKey: '', accessKeyId: '', accessKeySecret: '' }) } catch (e) { showError(e, 'TTS 配置保存失败') } finally { saving.value = false } }
async function testTtsConnection() { testingTts.value=true; clearError(); ttsTest.value=null; try { const result=await request('/admin/ai/tts/connection-test',{method:'POST'}); if(!result.ready)showError(result,'TTS 连接测试失败'); else ttsTest.value=result } catch(e) { showError(e,'TTS 连接测试失败') } finally { testingTts.value=false } }
async function checkTtsAccount() { testingAccount.value=true; clearError(); accountTest.value=null; try { const result=await request('/admin/ai/tts/account-check',{method:'POST',body:JSON.stringify({accountId:consoleAccountId.value})}); if(!result.ready)showError(result,'账号核验失败'); else accountTest.value=result } catch(e) { showError(e,'账号核验失败') } finally { testingAccount.value=false } }
async function testTemporaryToken() { testingTemporaryToken.value=true; clearError(); temporaryTokenTest.value=null; try { const result=await request('/admin/ai/tts/temporary-token-test',{method:'POST',body:JSON.stringify({nlsToken:temporaryNlsToken.value,text:temporaryText.value,voice:tts.voice,sampleRate:tts.sampleRate})}); temporaryTokenTest.value=result; /* 试听不改变数据库 Token；使用保存按钮显式持久化。 */ } catch(e) { showError(e,'临时 Token 测试失败') } finally { testingTemporaryToken.value=false } }
async function enableTemporaryTokenProduction() { changingProductionToken.value=true; clearError(); try { const data=await request('/admin/ai/tts/temporary-token-production',{method:'POST',body:JSON.stringify({nlsToken:temporaryNlsToken.value})}); tts.temporaryTokenProductionEnabled=data.enabled; temporaryNlsToken.value=''; temporaryTokenTest.value={ready:true,message:data.message,audioDataUrl:temporaryTokenTest.value?.audioDataUrl} } catch(e) { showError(e,'保存临时 Token 失败') } finally { changingProductionToken.value=false } }
async function disableTemporaryTokenProduction() { changingProductionToken.value=true; clearError(); try { const data=await request('/admin/ai/tts/temporary-token-production',{method:'DELETE'}); tts.temporaryTokenProductionEnabled=data.enabled; temporaryTokenTest.value={ready:true,message:data.message} } catch(e) { showError(e,'停用临时 Token 参数失败') } finally { changingProductionToken.value=false } }
function value(row, key) { return row[key] ?? row[key.toUpperCase()] ?? '-' }
function rate(model, period, key) { return model.pricing?.[period]?.[key] ?? '-' }
function periodLabel(row) { return value(row, 'pricing_period') === 'peak' ? '高峰' : value(row, 'pricing_period') === 'off_peak' ? '空闲' : '历史价格' }
function time(value) { if (!value) return '-'; return new Intl.DateTimeFormat('zh-CN', { timeZone: 'Asia/Shanghai', month: '2-digit', day: '2-digit', hour: '2-digit', minute: '2-digit', hour12: false }).format(new Date(value)) }
onMounted(load)
</script>

<template>
  <section>
    <div class="page-heading"><div><h1>AI 模型与费用</h1><p>管理可用模型、规格、冻结价格与调用账本；不展示用户问题和回答正文。</p></div><button class="primary-button add" @click="createModel">+ 添加模型</button></div>
    <div class="notice pricing-sync"><strong>DeepSeek 官网价格自动同步</strong><small>北京时间每天 22:00 核验；高峰为工作日 09:00–12:00、14:00–18:00，其余为空闲时段。最近检查：{{ time(pricingStatus.lastCheckedAt) }} · {{ pricingStatus.lastStatus === 'success' ? '正常' : pricingStatus.lastStatus === 'failed' ? '失败，继续使用上一有效版本' : '等待首次运行' }}</small></div>
    <div class="tabs"><button :class="{active:tab==='models'}" @click="tab='models'">模型配置</button><button :class="{active:tab==='usage'}" @click="tab='usage'">日志与费用</button><button :class="{active:tab==='tts'}" @click="tab='tts'">语音合成</button></div>
    <div v-if="loading" class="panel state">正在读取 AI 配置…</div>
    <template v-else-if="tab==='models'">
      <div class="model-grid">
        <article v-for="model in models" :key="model.id" class="panel model-card">
          <div class="model-top"><div><span class="spec">{{ model.specification }}</span><span v-if="model.defaultModel" class="default">默认</span><h3>{{ model.displayName }}</h3><code>{{ model.providerCode }} / {{ model.modelCode }}</code></div><span :class="['state-pill', model.enabled ? 'on' : 'off']">{{ model.enabled ? '已启用' : '已停用' }}</span></div>
          <dl v-if="!model.priceManaged"><div><dt>凭据</dt><dd>{{ model.credentialConfigured ? '已配置' : '未配置' }}</dd></div><div><dt>输入价</dt><dd>{{ model.inputPerMillion }} {{ model.currency }} / 百万 token</dd></div><div><dt>输出价</dt><dd>{{ model.outputPerMillion }} {{ model.currency }} / 百万 token</dd></div></dl>
          <div v-else class="official-pricing"><div class="pricing-head"><span>官网自动同步 · CNY / 百万 token</span><b>{{ model.currentPricingPeriod === 'peak' ? '当前高峰' : '当前空闲' }}</b></div><div class="pricing-grid"><div><strong>空闲</strong><span>缓存命中 {{ rate(model,'offPeak','inputCacheHit') }}</span><span>缓存未命中 {{ rate(model,'offPeak','inputCacheMiss') }}</span><span>输出 {{ rate(model,'offPeak','output') }}</span></div><div><strong>高峰</strong><span>缓存命中 {{ rate(model,'peak','inputCacheHit') }}</span><span>缓存未命中 {{ rate(model,'peak','inputCacheMiss') }}</span><span>输出 {{ rate(model,'peak','output') }}</span></div></div><small>版本 {{ model.pricing?.modelVersion || '-' }} · 生效记录 {{ time(model.priceEffectiveAt) }}</small></div>
          <div v-if="Number(model.inputPerMillion)===0 && Number(model.outputPerMillion)===0" class="price-warning">价格尚未核实，小程序会阻止调用。</div>
          <button class="edit" @click="editModel(model)">编辑配置</button>
        </article>
      </div>
    </template>
    <template v-else-if="tab==='usage'">
      <div class="panel budget-card"><div><h3>本月费用预算</h3><p>已用 {{ usage.budget?.spent_amount || 0 }} + 预留 {{ usage.budget?.reserved_amount || 0 }} {{ usage.budget?.currency || budget.currency }}</p><div class="budget-track"><i :style="{width:budgetRate+'%'}"></i></div></div><div class="budget-actions"><form @submit.prevent="saveBudget"><input v-model="budget.limitAmount" type="number" min="0.000001" step="0.000001" placeholder="本月上限" :disabled="saving"/><select v-model="budget.currency" :disabled="saving"><option>CNY</option><option>USD</option></select><button class="primary-button" :disabled="saving">{{ saving ? '保存中…' : '保存预算' }}</button></form><p v-if="budgetFeedback" :class="['budget-feedback',budgetFeedback.type]" role="status">{{ budgetFeedback.type==='success' ? '✓ ' : '!' }}{{ budgetFeedback.text }}</p></div></div>
      <div class="panel log-panel"><table><thead><tr><th>时间</th><th>模型 / 规格</th><th>状态</th><th>Token</th><th>结算费用</th><th>请求 ID</th><th>错误 / 操作</th></tr></thead><tbody><tr v-for="row in usage.logs" :key="value(row,'id')"><td>{{ time(value(row,'started_at')) }}</td><td>{{ value(row,'display_name') }}<small>{{ value(row,'specification') }}</small></td><td>{{ value(row,'state') }}</td><td>{{ value(row,'input_tokens') }} / {{ value(row,'output_tokens') }}<small>{{ periodLabel(row) }} · 命中 {{ value(row,'cache_hit_input_tokens') }} · 未命中 {{ value(row,'cache_miss_input_tokens') }}</small></td><td>{{ value(row,'settled_amount') }} {{ value(row,'currency') }}</td><td><code>{{ value(row,'provider_request_id') }}</code></td><td>{{ value(row,'error_code') }} <button v-if="value(row,'state')==='unknown'" class="reconcile" @click="reconcile(row)">核对费用</button></td></tr><tr v-if="!usage.logs.length"><td colspan="7" class="empty">暂无 AI 调用记录</td></tr></tbody></table></div>
    </template>
    <template v-else>
      <form class="panel tts-card" @submit.prevent="saveTts"><div class="tts-heading"><div><h3>阿里云语音合成</h3><p>AppKey 与 AccessKey 仅加密保存在服务端，不下发到小程序。</p></div><span :class="['state-pill',tts.ready?'on':'off']">{{ tts.ready ? '凭据已配置' : '待配置' }}</span></div><div class="form-grid"><label class="wide">接口地址<input v-model.trim="tts.endpoint" type="url" required/></label><label>英语音色<input v-model.trim="tts.voice" required placeholder="例如 eva"/></label><label>采样率<select v-model.number="tts.sampleRate"><option :value="8000">8000 Hz</option><option :value="16000">16000 Hz</option></select></label><label>项目 AppKey<input v-model="tts.appKey" type="password" :placeholder="tts.appKeyConfigured?'已配置；留空不修改':'请输入 AppKey'"/></label><label>AccessKey ID<input v-model="tts.accessKeyId" type="password" :placeholder="tts.accessKeyIdConfigured?'已配置；留空不修改':'请输入 AccessKey ID'"/></label><label>AccessKey Secret<input v-model="tts.accessKeySecret" type="password" :placeholder="tts.accessKeySecretConfigured?'已配置；留空不修改':'请输入 AccessKey Secret'"/></label></div><p v-if="ttsTest" :class="['tts-test',ttsTest.ready?'success':'failed']">{{ ttsTest.message }}</p><div class="tts-actions"><span>“测试连接”在已保存临时 Token 时仅检查配置，否则申请 NLS Token；不会合成音频或上传 OSS。</span><div><button type="button" class="test-button" :disabled="testingTts" @click="testTtsConnection">{{ testingTts?'测试中…':'测试连接' }}</button><button class="primary-button" :disabled="saving">{{saving?'保存中…':'保存 TTS 配置'}}</button></div></div><div class="tts-tools"><section class="tts-tool"><h4>核验已保存 AccessKey 的账号</h4><p>输入阿里云控制台“账号 UID”（仅本次比对，不保存）。服务端将用已保存的 AccessKey 调用 STS，并继续校验 NLS Token。</p><div class="tts-tool-row"><input v-model.trim="consoleAccountId" inputmode="numeric" autocomplete="off" placeholder="阿里云账号 UID"/><button type="button" class="test-button" :disabled="testingAccount" @click="checkTtsAccount">{{ testingAccount?'核验中…':'核验账号' }}</button></div><p v-if="accountTest" :class="['tts-test',accountTest.ready?'success':'failed']">{{ accountTest.message }}<span v-if="accountTest.accountIdMasked">（已识别：{{ accountTest.accountIdMasked }}）</span></p></section><section class="tts-tool"><h4>临时 NLS Token 试听与生产</h4><p>试听仅用于当前请求。点击“保存 Token 到系统参数”会将 Token 加密存入数据库，供小程序按需生成音频；重启仍有效，过期后需更新。</p><label>NLS 临时 Token<input v-model="temporaryNlsToken" type="password" autocomplete="off" placeholder="粘贴临时 NLS Token"/></label><label>试听文本<input v-model.trim="temporaryText" maxlength="300" placeholder="不超过 300 个字符"/></label><div class="tts-tool-row"><button v-if="tts.temporaryTokenProductionEnabled" type="button" class="test-button" :disabled="changingProductionToken" @click="disableTemporaryTokenProduction">{{ changingProductionToken?'处理中…':'软删除已保存 Token' }}</button><span v-else></span><button type="button" class="test-button" :disabled="testingTemporaryToken" @click="testTemporaryToken">{{ testingTemporaryToken?'生成中…':'生成并试听' }}</button></div><p v-if="temporaryTokenTest" class="tts-test success">{{ temporaryTokenTest.message }}</p><audio v-if="temporaryTokenTest?.audioDataUrl" controls :src="temporaryTokenTest.audioDataUrl">浏览器不支持音频播放。</audio><button type="button" class="production-button" :disabled="changingProductionToken || !temporaryNlsToken.trim()" @click="enableTemporaryTokenProduction">{{ changingProductionToken?'保存中…':'保存 Token 到系统参数' }}</button><p v-if="tts.temporaryTokenProductionEnabled" class="production-state">临时 Token 已加密保存到系统参数：小程序生成短文/单词音频时由后端读取，过期后需更新。</p></section></div></form>
      <div class="panel log-panel"><table><thead><tr><th>时间</th><th>目标</th><th>音色</th><th>字符数</th><th>状态</th><th>请求 ID</th><th>错误</th></tr></thead><tbody><tr v-for="row in tts.logs" :key="value(row,'id')"><td>{{time(value(row,'created_at'))}}</td><td>{{value(row,'target_type')}}</td><td>{{value(row,'voice')}}</td><td>{{value(row,'char_count')}}</td><td>{{value(row,'state')}}</td><td><code>{{value(row,'provider_request_id')}}</code></td><td>{{value(row,'error_code')}}</td></tr><tr v-if="!tts.logs?.length"><td colspan="7" class="empty">暂无语音合成记录</td></tr></tbody></table></div>
    </template>
  </section>

  <div v-if="showForm" class="modal-mask"><form class="model-modal" @submit.prevent="saveModel"><div class="modal-head"><div><h2>{{ form.id ? '编辑模型' : '添加模型' }}</h2><p>API Key 只用于写入加密配置，保存后不回显。</p></div><button type="button" @click="showForm=false">×</button></div><div class="form-grid"><label>供应商<input v-model.trim="form.providerCode" required/></label><label>模型代码<input v-model.trim="form.modelCode" required/></label><label>显示名称<input v-model.trim="form.displayName" required/></label><label>规格<select v-model="form.specification"><option value="flash">Flash</option><option value="pro">Pro</option><option value="custom">自定义</option></select></label><label class="wide">API 地址<input v-model.trim="form.baseUrl" type="url" required/></label><label>密钥参数名<input v-model.trim="form.apiKeyParamKey" required/></label><label>API Key<input v-model="form.apiKey" type="password" :placeholder="form.credentialConfigured ? '已配置；留空不修改' : '输入后加密保存'"/></label><div v-if="form.providerCode.toLowerCase()==='deepseek'" class="wide official-managed">DeepSeek 价格由服务端每天 22:00 从官网自动同步，管理员无需也不能手工录入。</div><template v-else><label>输入价 / 百万 token<input v-model.number="form.inputPerMillion" type="number" min="0" step="0.000001" required/></label><label>输出价 / 百万 token<input v-model.number="form.outputPerMillion" type="number" min="0" step="0.000001" required/></label><label>货币<select v-model="form.currency"><option>CNY</option><option>USD</option></select></label></template><label>最大输出 token<input v-model.number="form.maxOutputTokens" type="number" min="1" max="8192"/></label><label>超时秒数<input v-model.number="form.timeoutSeconds" type="number" min="5" max="120"/></label></div><div class="checks"><label><input v-model="form.enabled" type="checkbox"/> 启用</label><label><input v-model="form.defaultModel" type="checkbox"/> 设为默认模型</label></div><div class="modal-actions"><button type="button" @click="showForm=false">取消</button><button class="primary-button" :disabled="saving">{{ saving ? '保存中…' : '保存模型' }}</button></div></form></div>
</template>

